INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('3c91c83c-3f19-4903-aab5-4a21212c6812', 'Spider Crawl', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities. A staple exercise that belongs in most training programs.', '88451201', '88451201-Spider-Crawl-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Set up in the starting position for Spider Crawl. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Spider Crawl', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3c91d87d-27c3-4501-bf84-8de0606f4221', 'Chest Press (Plate Loaded Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. Secondary activation of your triceps, front delts provides additional muscle engagement. The fixed path allows you to focus purely on muscular effort. A well-developed chest contributes to upper body strength and aesthetics.', '5761201', '05761201-Lever-Chest-Press-(plate-loaded)_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.260518+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('3c9e3c3b-e92c-45e9-b856-9381c4a35e78', 'Push Up To Side Plank', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise focuses on your pectorals for improved chest strength and development. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '71731201', '71731201-Push-Up-to-Side-Plank-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'side_plank', 'Push Up To Side Plank', 'bench_press, chest_fly, dip, tricep_pushdown', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3ca2eae7-cd9c-4c47-9947-63cda95bc952', 'Patrick Step From Stepbox (Step Platform)', 'Legs', 'Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Bodyweight Patrick Step From Stepbox is a lower body stepping exercise that targets your full body. Secondary activation of your quads provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '96021201', '96021201-Bodyweight-Patrick-Step-from-StepBox-(female)_Thig.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Bodyweight Patrick Step From Stepbox. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Patrick Step From Stepbox', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3ca52d33-37c0-4fbe-9341-fcf5968b7004', 'Side Step Diagonal Punches', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic stepping movement gets your heart rate up while developing explosive strength. The shoulders assist throughout the movement, making this a well-rounded exercise. Plyometric training builds explosive power that transfers to sports and daily activities. Progress gradually by increasing resistance over time.', '61101201', '61101201-Side-Step-Diagonal-Punches-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Diagonal Punches. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Side Step Diagonal Punches', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3cc23a84-eb74-433e-a6d1-4fa2cf59f27a', 'Shoulders Tap Front Step', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Shoulders Tap Front Step builds reactive power and improves conditioning. You''ll also feel your quads working to support the movement. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '72681201', '72681201-Shoulders-Tap-Front-Step-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Shoulders Tap Front Step. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Shoulders Tap Front Step', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3cc88a40-b77c-41f5-b0ca-4ef6a8d1ec87', 'Seated Arms Archer Back Rotation - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This rotation exercise engages your core for improved core stability and strength. The seated position helps isolate the target muscles by removing momentum. Building core stability helps with everything from heavy deadlifts to daily activities.', '89441201', '89441201-Seated-Alternate-Arms-Archer-Back-Rotation-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Alternate Arms Archer Back Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Seated Arms Archer Back Rotation - Alternating', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3ce1e6a7-b4a7-4ed6-b2e5-2e241c8b9fa5', 'Weighted Donkey Kickback', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{}'::text[], 'Build stronger glutes with this kicking movement focused on hip extension. Your hamstrings work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '104331201', '104331201-Weighted-Donkey-Kickback-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Keep your upper arm stationary and extend your forearm back. 2. Squeeze at full extension, then return with control. 3. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'glute_kickback', 'Weighted Donkey Kickback', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3cf81511-8d54-4816-8b78-6bdd91183583', 'Chest Dip - On Dip Pull Up Cage (Pull-Up Bar)', 'Back', 'Pull-Up Bar, Dip Bars', '{"Lats","Upper Back"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Chest Dip (on Dip Pull Up Cage) is a pulling exercise that targets your chest muscles. Your biceps, upper back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '90051201', '90051201-Chest-Dip-(on-dip-pull-up-cage)-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. Works well for chest activation.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Chest Dip', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3cffb075-3e86-4b8e-9491-15223c2714f0', 'Lying Ankle Tap To Star Pose', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Ankle Tap To Star Pose, focusing on your abs. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '66391201', '66391201-Lying-Ankle-Tap-to-Star-Pose-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Ankle Tap To Star Pose. 2. Set up in the starting position for Lying Ankle Tap To Star Pose. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'general_exercise', 'Lying Ankle Tap To Star Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3d0d02ac-4ce2-4e0d-8c61-070efd59ee2b', 'Seated Stick Pass Around Stretch', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this stretching movement focusing on your delts. The seated position helps isolate the target muscles by removing momentum. Shoulder development enhances both performance and upper body aesthetics.', '87371201', '87371201-Seated-Stick-Pass-Around-Stretch-(female)_Shoulder.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Stick Pass Around Stretch. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Stick Pass Around Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3d0d0b21-fffd-4af8-b84b-b3918a9766b2', 'Hip Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '51361201', '51361201-Hip-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction. Works well for abs activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Hip Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3d0d1e3a-f405-4bf1-8989-87db3f1fe997', 'Superman Back Raise', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'The Superman Back Raise is a raising exercise that develops back strength and muscle. You''ll also feel your glutes working to support the movement. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '89951201', '89951201-Superman-Back-Raise-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Raise the weight in the prescribed direction for Superman Back Raise. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_extension', 'Superman Back Raise', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3d2239d6-42ab-4ab8-a197-07206482fc72', 'Seated Wide Angle Pose Sequence', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Seated Wide Angle Pose Sequence helps improve mobility and prevent stiffness. Being seated provides stability, allowing you to focus on the working muscles. Flexibility work like this enhances performance and prevents stiffness.', '43061201', '43061201-Seated-Wide-Angle-Pose-Sequence-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:36.848698+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Wide Angle Pose Sequence. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 52, 2, 6, FALSE, TRUE, 'yoga', 'Seated Wide Angle Pose Sequence', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3d5ec05b-e952-4051-bfe8-3af8ff51f725', 'Jog And Drop', 'Full Body', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities. This variation is excellent for building mind-muscle connection.', '77801201', '77801201-Jog-and-Drop-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Set up in the starting position for Jog And Drop. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Cardio', 50, 7, 8, TRUE, TRUE, 'running', 'Jog And Drop', 'cycling, rowing_cardio, jump_rope', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3d60777c-4c2d-4d69-ac5a-2e58fe3e95fc', 'Decline Bench Press - Reverse Grip (Smith Machine)', 'Chest', 'Smith Machine, Decline Bench', '{Pectorals}'::text[], '{"Front Delts","Triceps"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. Declining shifts the emphasis to hit the muscles from a different angle. The fixed path allows you to focus purely on muscular effort. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '7541201', '07541201-Smith-Decline-Reverse-Grip-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:25.233728+00', '1. Set the Smith machine bar to the appropriate starting height for Smith Decline Reverse Grip Press. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting.', 'Press', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 81, 7, 8, TRUE, TRUE, 'general_exercise', 'Smith Decline Press - Reverse Grip', 'Decline Press - Reverse Grip', FALSE, 'smith_machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('3d66dc8c-4e2b-44f3-933e-fac5b3f1c81f', 'Triceps Extension Push Up (TRX)', 'Arms', 'TRX', '{"Triceps"}'::text[], '{"Front Delts"}'::text[], 'Build stronger triceps with this pushing exercise for bigger arms. Secondary activation of your triceps, front delts provides additional muscle engagement. The TRX allows you to adjust difficulty by changing your body angle. Dedicated arm training builds both strength and muscular definition.', '11491201', '11491201-Suspender-Triceps-Extension-Push-Up-(female)_Upper.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Triceps Extension Push Up. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'tricep_extension', 'Suspender Triceps Extension Push Up', 'tricep_pushdown, close_grip_bench', TRUE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('3d72683b-2334-404f-9cc8-fa359bb89ab1', 'Trunk Twist Hop', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Build power and athleticism with this high-intensity twisting exercise that challenges your entire body. Your abs work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '76741201', '76741201-Trunk-Twist-Hop-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Rotate your torso through the movement pattern for Trunk Twist Hop. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'russian_twist', 'Trunk Twist Hop', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('3d7dc0b4-59bb-4106-99d4-a4ef8cb30996', 'Rocky Pull Up Pulldown (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Rocky Pull Up Pulldown is a pulling exercise that targets your latissimus dorsi for a wider back. Secondary activation of your biceps, upper back provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '6781201', '06781201-Rocky-Pull-Up-Pulldown_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Rocky Pull Up Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', FALSE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3d81dc36-9ea1-47ed-8171-e1e6f481d801', 'Half Plyo Squat Twist', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Work your side abdominals with this squatting exercise that strengthens your obliques. The abs assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '63811201', '63811201-Half-Plyo-Squat-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'squat', 'Half Plyo Squat Twist', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('3d93cff7-7af5-4b3c-a568-1422939cd5a1', 'Kneeling Single Arm Pulldown (Band)', 'Back', 'Resistance Band, Anchor Point', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Band Kneeling One Arm Pulldown is a pulling exercise that targets your latissimus dorsi for a wider back. Secondary activation of your biceps, upper back provides additional muscle engagement. Kneeling helps eliminate lower body momentum from the movement. Bands are joint-friendly and portable, perfect for any training environment. A strong back improves posture, prevents injury, and balances pressing movements.', '9831201', '09831201-Band-kneeling-one-arm-pulldown_Back.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Secure the resistance band appropriately for Band Kneeling One Arm Pulldown. 2. Kneel on the floor (use a pad for comfort if needed). 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Complete all reps on one side, then switch to the other side. 7. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Kneeling Single Arm Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('3d961f18-5867-4a05-98a6-9488aa8175f6', 'Torso Rotation (Machine)', 'Core', 'Machine', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This rotation movement focuses on your obliques for a complete core workout. Machine exercises are great for isolating muscles and training to failure safely. A strong core improves posture, protects your spine, and enhances all other lifts.', '107141201', '107141201-Lever-Torso-Rotation-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Torso Rotation. 2. Rotate your torso through the movement pattern for Lever Torso Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Lever Torso Rotation', 'squat, bench_press, deadlift', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('3d99e6b8-fbde-4feb-838f-21108c18c3e7', 'Incline 30 Degrees Bench Pre - Reverse Grip (Dumbbell)', 'Arms', 'Dumbbells', '{"Forearms"}'::text[], '{}'::text[], 'The Dumbbell Incline Reverse Grip 30 Degrees Bench Pre strengthens your forearms and grip through a movement motion. The incline angle shifts emphasis toward the upper portion of the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Arm strength supports grip, pulling, and pushing in compound movements.', '12141201', '12141201-Dumbbell-Incline-Reverse-Grip-30-Degrees-Bench-Pre.mp4', 'male', FALSE, '2025-12-03 23:26:22.644637+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Reverse Grip 30 Degrees Bench Pre. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'general_exercise', 'Incline 30 Degrees Bench Pre - Reverse Grip', 'Incline 30 Degrees Bench Pre - Reverse Grip', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('3d9fc208-6f73-405c-bc90-e1156aecde6f', 'Hip Raise Bridge', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. The hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '4861201', '04861201-Hip-Raise-Bridge_Waist.mp4', 'female', FALSE, '2025-12-03 23:26:34.073704+00', '1. Raise the weight in the prescribed direction for Hip Raise Bridge. 2. Lower with control, maintaining tension throughout. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'glute_bridge', 'Hip Raise Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3dab2fd4-b248-4f74-a087-a5624d6b92d4', 'Balance Disk Standing', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Balance Disk Standing is a lower body movement exercise that targets your full body. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '98111201', '98111201-Balance-Disk-Standing-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Balance Disk Standing. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'balance', 'Balance Disk Standing', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3daef9ee-1fa0-4600-9544-e61d7dfc8cd7', 'Side Lying Inner Thigh Up And Down', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Bodyweight Side Lying Inner Thigh Up And Down is a lower body movement exercise that targets your adductors. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '65891201', '65891201-Bodyweight-Side-Lying-Inner-Thigh-Up-and-Down-(mal.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Bodyweight Side Lying Inner Thigh Up And Down. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_adduction', 'Side Lying Inner Thigh Up And Down', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3dbf5f39-f715-41b9-a52e-cc6a038435ef', 'Standing Front Shoulder Tap', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Front Shoulder Tap is an arm movement exercise targeting your full body. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Arm strength supports grip, pulling, and pushing in compound movements.', '73171201', '73171201-Standing-Front-Shoulder-Tap-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Front Shoulder Tap. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing Front Shoulder Tap', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3dc2db0f-86b8-495d-a5de-395fd92ede14', 'Top Pull Up Hold (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. You''ll also feel your biceps, upper back working to support the movement. No equipment needed—your body provides all the resistance. Back development is crucial for pulling strength and overall upper body function. Focus on controlled form throughout each repetition.', '49831201', '49831201-Top-Pull-up-Hold-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Hold the position for the prescribed time, maintaining tension.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'pull_up', 'Top Pull Up Hold', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', TRUE, 3, 90, 4, 70, 88, 95, 65),
('3dc95221-1367-4719-aabc-35626d1d61d2', 'Seated Hip External Rotator And Hip Extensor Stret', 'Core', 'Bodyweight', '{"Hips"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Hip External Rotator And Hip Extensor Stret, focusing on your core. The seated position helps isolate the target muscles by removing momentum. Building core stability helps with everything from heavy deadlifts to daily activities.', '19181201', '19181201-Seated-Hip-External-Rotator-And-Hip-Extensor-Stret.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Hip External Rotator And Hip Extensor Stret. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'external_rotation', 'Seated Hip External Rotator And Hip Extensor Stret', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3dceeee4-4317-484a-b192-4b1a67897177', 'Pulsing Glute Bridge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'This bridging exercise isolates your glutes for improved hip strength and power. The hamstrings assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness. Focus on controlled form throughout each repetition.', '63861201', '63861201-Pulsing-Glute-Bridge-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Keep tension on the target muscles throughout. Great for building strength in your glutes.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Pulsing Glute Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3dd71c0d-036c-46cd-896c-5a0f1f65e0c1', 'Single Leg Plank - Straight Arm (TRX)', 'Legs', 'TRX', '{"Core","Abs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Strengthen your midsection with this stabilization movement that works your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. Suspension training adds instability, increasing core activation throughout. Building core stability helps with everything from heavy deadlifts to daily activities.', '11341201', '11341201-Suspender-Single-Leg-Plank-(straight-arm)-(female).mp4', 'female', FALSE, '2025-12-03 23:26:39.472701+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspender Single Leg Plank. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'plank', 'Suspender Single Leg Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'trx', TRUE, 3, 90, 4, 68, 85, 85, 70),
('3ddc7edd-cb0a-41ca-8da5-e1e5e232fc08', 'Cross Mountain Climber (Against Wall)', 'Core', 'Wall', '{"Abs"}'::text[], '{"Hip Flexors","Shoulders"}'::text[], 'The Cross Mountain Climber Against Wall is an explosive exercise that combines cardiovascular training with dynamic climbing movements. Secondary activation of your shoulders, core provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning.', '74461201', '74461201-Cross-Mountain-Climber-against-Wall-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Position yourself at the appropriate distance from a wall. 2. From plank position, drive one knee toward your chest. 3. Quickly switch legs, bringing the other knee forward. 4. Continue alternating at a quick pace while maintaining plank form. 5. Repeat for the prescribed number of repetitions. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 42, 9, 8, TRUE, TRUE, 'mountain_climber', 'Cross Mountain Climber Against Wall', 'burpee, plank, high_knees', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('3df74966-9918-44dc-ae70-4e53c42c533f', 'Squat Front Kick', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements. Focus on controlled form throughout each repetition. Consistency with this movement will yield noticeable results.', '78941201', '78941201-Squat-Front-Kick-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control. This variation specifically emphasizes the quads. Variation: Squat Front Kick.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat Front Kick', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3dfbeb58-123f-4ab7-a69d-bc60a5acfe05', 'Squat (Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Bands are joint-friendly and portable, perfect for any training environment. Strong legs are the foundation for athletic performance and functional fitness.', '57491201', '57491201-Band-squat-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 90, 7, 8, TRUE, TRUE, 'squat', 'Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('3e179adc-fe8c-479f-b206-a96ac3e7ade2', 'Standing Single Arm Triceps Extension (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. Performing this standing challenges your balance and core engagement. The cable setup allows you to adjust the angle of resistance. Dedicated arm training builds both strength and muscular definition.', '2311201', '02311201-Cable-Standing-One-Arm-Triceps-Extension_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing One Arm Triceps Extension. 2. Begin in a standing position with good posture. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 87, 5, 7, FALSE, TRUE, 'tricep_extension', 'Standing Single Arm Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('3e368d3b-3569-4ece-999f-f3bca7583566', 'Triceps Kickback (Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'This kicking movement isolates your triceps for improved arm development. The hamstrings assist throughout the movement, making this a well-rounded exercise. The band creates increasing tension as it stretches, challenging the lockout. Dedicated arm training builds both strength and muscular definition.', '70391201', '70391201-Band-Triceps-Kickback-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Secure the resistance band appropriately for Band Triceps Kickback. 2. Keep your upper arm stationary and extend your forearm back. 3. Squeeze at full extension, then return with control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 55, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Triceps Kickback', 'tricep_pushdown, tricep_extension', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('3e378734-b45f-41c7-a31a-8e619b455fa2', 'Side Step Swing', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this swinging exercise that develops speed, power, and coordination. The quads assist throughout the movement, making this a well-rounded exercise. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '55601201', '55601201-Side-Step-Swing_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Set up a box or step platform at the appropriate height. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Step Swing', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3e474314-97ae-4a23-9a98-25acd949fd30', 'Landmine Squat With Linebacker Attachment (Landmine)', 'Legs', 'Landmine Attachment, Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. You''ll also feel your glutes, hamstrings working to support the movement. Leg training boosts metabolism and builds functional, real-world strength. Keep your core engaged throughout the exercise.', '86911201', '86911201-Landmine-Squat-with-Linebacker-Attachment-(male)_T.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement. This variation specifically emphasizes the quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'squat', 'Landmine Squat With Linebacker Attachment', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('3e483378-80e3-4d56-86ea-7bb560d55144', 'Assisted Triceps Dip - Kneeling (Dip Bars)', 'Arms', 'Dip Bars', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This dipping movement isolates your triceps for improved arm development. You''ll also feel your triceps, front delts working to support the movement. The kneeling position adds a core stability challenge. No equipment needed—your body provides all the resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '25751201', '25751201-Assisted-Triceps-Dip-(kneeling)-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Lower your body by bending your elbows to about 90 degrees. 3. Push back up until your arms are fully extended. 4. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Assisted Triceps Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3e524c8b-62cb-4cb5-b853-663b8ab01f75', 'Wide Air Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Wide Air Squat is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '48051201', '48051201-Wide-Air-Squat_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Focus on squeezing the target muscle at peak contraction. Include this in your legs training.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Wide Air Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3e5628c1-89cc-4f9c-9201-af5bf1e583e0', 'Lying Superman Soar', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Glutes","Upper Back"}'::text[], 'The Lying Superman Soar is a movement exercise that develops back strength and muscle. Secondary activation of your glutes provides additional muscle engagement. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '90391201', '90391201-Lying-Superman-Soar-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Superman Soar. 2. Set up in the starting position for Lying Superman Soar. 3. Execute the movement with proper form, focusing on your lower back. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_extension', 'Lying Superman Soar', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3e562974-a172-4d8c-8f9c-9234bfe6c31a', 'Lying Back Raise - Alternating', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'The Lying Alternate Back Raise is a raising exercise that develops back strength and muscle. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. A strong back improves posture, prevents injury, and balances pressing movements.', '89781201', '89781201-Lying-Alternate-Back-Raise-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:25.737494+00', '1. Lie down in the appropriate position for Lying Alternate Back Raise. 2. Raise the weight in the prescribed direction for Lying Alternate Back Raise. 3. Lower with control, maintaining tension throughout. 4. Alternate between sides/arms/legs with each repetition. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'back_exercise', 'Lying Back Raise - Alternating', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3e67335a-64f4-4a76-ae62-f11763cd5e0d', 'Oblique Crunch - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{}'::text[], 'Build a stronger core with the Alternate Oblique Crunch, focusing on your abs. Secondary activation of your abs provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '52801201', '52801201-Alternate-Oblique-Crunch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.412523+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Alternate between sides/arms/legs with each repetition. 5. Complete all reps with control before resting. Keep your core engaged for stability.', NULL, 'Pull', 'Compound', 'Bilateral (Alternating)', NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Oblique Crunch - Alternating', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3e69e953-5cfe-40c0-a31c-777c414ba3fe', 'Overhead Single Arm Triceps Extension (Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. Resistance bands provide accommodating resistance that increases through the range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '72891201', '72891201-Band-Overhead-Single-Arm-Triceps-Extension-(female.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Overhead Single Arm Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'tricep_extension', 'Overhead Single Arm Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('3e6a3c89-d623-40a6-8f8b-6cc04cc68cc8', 'Contralateral Glute Bridge Single Arm Che (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. You''ll also feel your hamstrings working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Leg training boosts metabolism and builds functional, real-world strength.', '76521201', '76521201-Dumbbell-Contralateral-Glute-Bridge-Single-Arm-Che.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 67, 7, 8, TRUE, TRUE, 'glute_bridge', 'Contralateral Glute Bridge Single Arm Che', 'hip_thrust, romanian_deadlift', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('3e944edd-46bd-46da-9341-e03052bb81d1', 'Lying Triceps Extension - Rope (Cable)', 'Arms', 'Cables', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Cable Lying Triceps Extension (with Rope) targets your triceps through a extension motion. Performing this lying down removes momentum for stricter form. Cable resistance creates smooth, continuous muscle engagement. Dedicated arm training builds both strength and muscular definition.', '43531201', '43531201-Cable-Lying-Triceps-Extension-(with-Rope)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lying Triceps Extension. 2. Lie down in the appropriate position for Cable Lying Triceps Extension. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lying Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('3e963ad2-eedd-4a7e-8c31-29140e33bcf6', 'Seated Marching (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your full body. The hip flexors assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Leg training boosts metabolism and builds functional, real-world strength.', '84161201', '84161201-Seated-Marching-on-a-Chair-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 37, 9, 8, FALSE, TRUE, 'marching', 'Seated Marching On A Chair', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('3ea3d23e-7b6e-409d-b20a-f2fc8b0c5d24', 'Thruster', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Shoulders"}'::text[], 'The Bodyweight Thruster is a lower body thrusting exercise that targets your full body. Your quads, shoulders work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '71821201', '71821201-Bodyweight-Thruster-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.60311+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum. This exercise is excellent for full body development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'thruster', 'Thruster', 'front_squat, shoulder_press, clean', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3ea699fd-5fb6-49bd-85fe-88e554fb5ea5', 'Renegade Row (Dumbbell)', 'Back', 'Dumbbells', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Dumbbell Renegade Row is a rowing exercise that builds thickness in your upper back. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. A strong back improves posture, prevents injury, and balances pressing movements.', '29801201', '29801201-Dumbbell-Renegade-Row_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Renegade Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'dumbbell_row', 'Renegade Row', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('3eaa7244-262a-4212-be0e-bd086c77dbff', 'Standing Hamstring Calf Stretch (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Calves"}'::text[], '{}'::text[], 'Target your hamstrings with this stretching stretch that helps restore range of motion. The lower back assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '84441201', '84441201-Standing-Hamstring-Calf-Stretch-(female)_Stretchin.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Begin in a standing position with good posture. 2. Move into the stretch position for Standing Hamstring Calf Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 30, 2, 6, FALSE, TRUE, 'calf_stretch', 'Standing Hamstring Calf Stretch', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('3eb7c021-e68c-4249-bdad-4ef91e84dc32', 'Standing Bent Knee Calf Raise From Deficit (Barbell)', 'Legs', 'Barbell, Step Platform', '{"Calves"}'::text[], '{}'::text[], 'Build stronger calves with this targeted raising exercise. Performing this standing challenges your balance and core engagement. Barbells enable bilateral loading for building raw strength. Lower body strength improves everything from walking to heavy compound lifts.', '94101201', '94101201-Barbell-Standing-Bent-Knee-Calf-Raise-from-Deficit.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Grip a barbell with hands at the appropriate width for Barbell Standing Bent Knee Calf Raise From Deficit. 2. Stand tall with your feet firmly planted. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Bent Knee Calf Raise From Deficit', 'calf_raise, seated_calf_raise', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('3ec6ceee-5a8c-403e-b225-13872480733b', 'Single Arm Front Raise (Cable)', 'Shoulders', 'Cables', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Build stronger shoulders with this raising movement focusing on your front delts. Cable resistance creates smooth, continuous muscle engagement. Strong shoulders improve overhead strength and support nearly all upper body movements.', '26891201', '26891201-Cable-One-Arm-Front-Raise-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable One Arm Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Complete all reps on one side, then switch to the other side. 5. Complete all reps with control before resting. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'front_raise', 'Single Arm Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('3ed6fb12-56c2-4e9f-89c1-41aa6d29138d', 'Lying Upright Row - SZ Bar (Cable)', 'Shoulders', 'Cables', '{"Side Delts"}'::text[], '{"Traps","Front Delts"}'::text[], 'Target your delts with the Cable Lying Upright Row (SZ Bar), an effective shoulder rowing exercise. You''ll also feel your traps working to support the movement. Performing this lying down removes momentum for stricter form. Cable resistance creates smooth, continuous muscle engagement. Strong shoulders improve overhead strength and support nearly all upper body movements.', '94921201', '94921201-Cable-Lying-Upright-Row-(SZ-bar)-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lying Upright Row. 2. Lie down in the appropriate position for Cable Lying Upright Row. 3. Pull the weight straight up along your body, leading with your elbows. 4. Raise until elbows reach shoulder height, then lower with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'upright_row', 'Lying Upright Row', 'lateral_raise, shoulder_press, shrug', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('3ed9fd51-84d8-49cb-b147-65c846dd82d9', 'Roll Rhomboids', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Flexibility work like this enhances performance and prevents stiffness. This is a great exercise for all fitness levels with proper scaling.', '54201201', '54201201-Roll-Rhomboids-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:36.38616+00', '1. Move into the stretch position for Roll Rhomboids. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Roll Rhomboids', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3eddbb15-a871-4e31-9069-0c5b00dbff2b', 'Feet Flat Bench Press (Barbell)', 'Chest', 'Barbell, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Barbell Feet Flat Bench Press, an effective pressing movement for upper body strength. You''ll also feel your triceps, front delts working to support the movement. Using a barbell provides stability for progressive overload. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '65841201', '65841201-Barbell-Feet-Flat-Bench-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'bench_press', 'Feet Flat Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('3ee01ee3-26eb-4bcf-8329-ffb7564ca4b7', 'Lying Arm Abduction', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Performing this lying down removes momentum for stricter form. Flexibility work like this enhances performance and prevents stiffness. Keep your core engaged throughout the exercise.', '72961201', '72961201-Lying-Arm-Abduction-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Arm Abduction. 2. Move into the stretch position for Lying Arm Abduction. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lying Arm Abduction', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3ee49c35-51c1-46a2-92a2-9f21ae77e7d6', 'Stair Up', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Stair Up is a movement exercise that primarily loads your quadriceps. Your glutes, calves work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '30091201', '30091201-Stair-Up-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Set up in the starting position for Stair Up. 2. Execute the movement with proper form, focusing on your quads. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Stair Up', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3eea910e-9dc3-409d-bcf6-b869d4b558d5', 'High Knee Star Tap', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads","Calves"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '56161201', '56161201-High-Knee-Star-Tap-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Set up in the starting position for High Knee Star Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'high_knees', 'High Knee Star Tap', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('3ef6e237-202b-4ee7-b2f1-3e68c5c38364', 'Weighted Hyperextension (Stability Ball)', 'Back', 'Stability Ball, Hyperextension Bench', '{"Lower Back"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build a stronger core with the Weighted Hyperextension (on Stability Ball), focusing on your abs. Secondary activation of your hamstrings, lower back provides additional muscle engagement. The stability ball adds an instability challenge that activates more stabilizer muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '8351201', '08351201-Weighted-Hyperextension-(on-stability-ball)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Position the stability ball as needed for Weighted Hyperextension. 2. Raise your torso by extending at the lower back/hips. 3. Lower with control, maintaining tension. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'back_extension', 'Weighted Hyperextension', 'good_morning, bird_dog, superman', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3f01c4f5-d192-447b-b8c9-a7455cbaa449', 'Decline Push Up (Against Wall)', 'Chest', 'Wall', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'The Decline Push Up Against Wall is a pushing exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. Declining shifts the emphasis to hit the muscles from a different angle. A well-developed chest contributes to upper body strength and aesthetics.', '74271201', '74271201-Decline-Push-Up-against-Wall-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.501166+00', '1. Position yourself at the appropriate distance from a wall. 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', 'Push Up', NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'push_up', 'Decline Push Up Against Wall', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3f1dcab6-377c-4fc5-8a02-7093b39280c1', 'Sumo Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Inner Thighs","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength. Works well as both a primary exercise or accessory movement.', '57221201', '57221201-Barbell-Sumo-Squat-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Sumo Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Sumo Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('3f227571-ba2f-44df-ac19-435bcae4081e', 'Kneeling Hip Abduction (Cable)', 'Legs', 'Cables', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'The Cable Kneeling Hip Abduction is a lower body movement exercise that targets your glute med/abductors. Secondary activation of your glutes provides additional muscle engagement. Kneeling helps eliminate lower body momentum from the movement. The cable setup allows you to adjust the angle of resistance. Lower body strength improves everything from walking to heavy compound lifts.', '67391201', '67391201-Cable-Kneeling-Hip-Abduction-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Hip Abduction. 2. Kneel on the floor (use a pad for comfort if needed). 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'hip_abduction', 'Kneeling Hip Abduction', 'hip_adduction, glute_bridge, clamshell', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('3f231173-1515-4993-b8b8-0287a07a7db7', 'Squat (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger quads with this squatting movement that develops leg drive and power. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Strong legs are the foundation for athletic performance and functional fitness.', '4131201', '04131201-Dumbbell-Squat_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('3f258ae1-c61d-4c55-803e-a8436697dcdc', 'Arms Lift Leg Kickback', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Rear Delts"}'::text[], 'A challenging plyometric exercise, the Arms Lift Leg Kickback builds reactive power and improves conditioning. Your hamstrings work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '69091201', '69091201-Arms-Lift-Leg-Kickback-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Keep your upper arm stationary and extend your forearm back. 2. Squeeze at full extension, then return with control. 3. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Arms Lift Leg Kickback', 'shoulder_press, lateral_raise, front_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3f2efa58-f9a9-4978-845e-b2d652dd6501', 'Straight Legs Pull Through - Rope (Cable)', 'Legs', 'Cables', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This pulling exercise isolates your glutes for improved hip strength and power. Secondary activation of your hamstrings provides additional muscle engagement. Cable resistance creates smooth, continuous muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '23241201', '23241201-Cable-Straight-Legs-Pull-Through-(with-rope)-(female).mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Straight Legs Pull Through. 2. Set up in the starting position for Cable Straight Legs Pull Through. 3. Execute the movement with proper form, focusing on your glutes. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Straight Legs Pull Through', 'deadlift, leg_curl, hip_thrust', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('3f396737-4017-4954-b2ff-0d4144251987', 'Pike Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Pike Push Up, an effective pushing movement for upper body strength. You''ll also feel your triceps, front delts working to support the movement. A versatile bodyweight movement perfect for home or gym training. A well-developed chest contributes to upper body strength and aesthetics.', '38181201', '38181201-Pike-Push-up-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:35.667316+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability. Great for building strength in your chest.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Pike Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3f4acb82-d500-40dc-8854-5e325fcb45bd', 'Lying Single Leg Butterfly', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Lying Single Leg Butterfly is a lower body flying exercise that targets your chest. You''ll also feel your front delts working to support the movement. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '73031201', '73031201-Lying-Single-Leg-Butterfly-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Single Leg Butterfly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'groin_stretch', 'Lying Single Leg Butterfly', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3f5d0eba-371f-4b82-8a04-2195eb0b82b7', 'Vertical Leg Raise - On Parallel Bars (Dip Bars)', 'Core', 'Dip Bars', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Vertical Leg Raise (on Parallel Bars) is a lower body raising exercise that targets your abs. Your hip flexors work as secondary movers, adding to the training stimulus. Lower body strength improves everything from walking to heavy compound lifts.', '36231201', '36231201-Vertical-Leg-Raise-(on-parallel-bars)-(female)-(VERSION-2)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Keeping legs mostly straight, raise them toward the ceiling. 2. Lower with control, stopping just before touching down. 3. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'dip', 'Vertical Leg Raise', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3f5ee1d1-15c1-4fbf-ad48-fd8cf613308f', 'Lying Shoulder Abduction (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your hip abductors. Your glutes work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. Bands are joint-friendly and portable, perfect for any training environment. Strong legs are the foundation for athletic performance and functional fitness.', '91961201', '91961201-Resistance-Band-Lying-Shoulder-Abduction-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Lying Shoulder Abduction. 2. Lie down in the appropriate position for Resistance Band Lying Shoulder Abduction. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lying Shoulder Abduction', 'lateral_raise, shoulder_press, front_raise', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('3f6260a3-399f-4060-9e98-4895b000ebc8', 'Shoulder Backbend Stretch', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build stronger shoulders with this stretching movement focusing on your delts. A versatile bodyweight movement perfect for home or gym training. Shoulder development enhances both performance and upper body aesthetics.', '55941201', '55941201-Shoulder-Backbend-Stretch-(VERSION-2)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:21.890719+00', '1. Set up in the starting position for Shoulder Backbend Stretch. 2. Execute the movement with proper form, focusing on your delts. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Shoulder Backbend Stretch', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3f638eb8-4b3a-4aa1-9e94-515d21bdf5df', 'Rear Delt Row - Rope (Cable)', 'Shoulders', 'Cables', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'The Cable Rear Delt Row (with Rope) is a rowing exercise that targets your rear delts for shoulder development. The upper back assist throughout the movement, making this a well-rounded exercise. Cables provide constant tension throughout the full range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '2031201', '02031201-Cable-Rear-Delt-Row-(with-rope)_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Adjust the cable machine to the correct height and attachment for Cable Rear Delt Row. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'rear_delt', 'Rear Delt Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('3f6f4603-4a49-4d55-808d-f614dd9e7d18', 'Standing 180 Abs Rotation', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build power and athleticism with this high-intensity rotation exercise that challenges your entire body. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '93491201', '93491201-Standing-180-Abs-Rotation-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand with feet about shoulder-width apart. 2. Rotate your torso through the movement pattern for Standing 180 Abs Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing 180 Abs Rotation', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3f71aeea-20be-47e5-a5cd-2d56300b60de', 'Chest Bench Press Grip Width (Flat Bench)', 'Chest', 'Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. A well-developed chest contributes to upper body strength and aesthetics.', '66291201', '66291201-Chest-Bench-Press---Grip-Width-(WRONG-RIGHT)-(female)_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Lower the weight toward your chest with control. 2. Press the weight up until your arms are extended (don''t lock elbows). 3. Repeat for the prescribed number of repetitions. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'bench_press', 'Chest Bench Press Grip Width', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3f873548-6adb-417e-aee9-9c41dd03e6c4', 'Mindful Breathing Meditation', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Flexibility work like this enhances performance and prevents stiffness. Quality repetitions are more important than quantity.', '58951201', '58951201-Mindful-Breathing-Meditation-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Move into the stretch position for Mindful Breathing Meditation. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'breathing', 'Mindful Breathing Meditation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3f89474f-fb46-4e2a-9229-fdf132bd8408', 'Incline Bench Two Arm Row - Reverse Grip (Dumbbell)', 'Back', 'Dumbbells, Incline Bench', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. Using an incline changes the angle of resistance for varied muscle recruitment. Using dumbbells requires more stabilization than barbell variations. Back development is crucial for pulling strength and overall upper body function.', '13311201', '13311201-Dumbbell-Reverse-Grip-Incline-Bench-Two-Arm-Row_Ba.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Reverse Grip Incline Bench Two Arm Row. 2. Use a reverse grip (opposite of the standard grip for this exercise). 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 85, 7, 9, TRUE, FALSE, 'incline_press', 'Incline Bench Two Arm Row - Reverse Grip', 'Incline Bench Two Arm Row - Reverse Grip', TRUE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('3f9e67e7-e914-4efe-beaa-5ffd9b6dcfc4', 'Body Open Cross Feet', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'A challenging plyometric exercise, the Body Open Cross Feet builds reactive power and improves conditioning. Secondary activation of your shoulders, core provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '88881201', '88881201-Body-Open-Cross-Feet-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Set up in the starting position for Body Open Cross Feet. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'boxing', 'Body Open Cross Feet', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3fa30bb6-b7c7-4806-9d15-a2c96e4babe4', 'Seated Leg Raise (Chair)', 'Core', 'Chair', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '83101201', '83101201-Seated-Leg-Raises-on-a-Chair-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keeping legs mostly straight, raise them toward the ceiling. 4. Lower with control, stopping just before touching down. 5. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 57, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Leg Raise On A Chair', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3fb1913f-cf37-496f-8b67-08f5095167c8', 'Seated Neck Stretch Circle', 'Neck', 'Bodyweight', '{"Neck"}'::text[], '{"Traps"}'::text[], 'The Seated Neck Stretch Circle is a flexibility exercise that targets your neck, helping to release tension and improve range of motion. Secondary activation of your upper back provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '81561201', '81561201-Sitting-Neck-Stretch-Circle-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Neck Stretch Circle. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'neck_stretch', 'Seated Neck Stretch Circle', 'stretch_hip, stretch_back', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3fb47a8b-a6f5-499b-bc4c-ade45d318246', 'Lateral Walk (Dumbbell)', 'Full Body', 'Dumbbells', '{"Full Body"}'::text[], '{}'::text[], 'The Dumbbell Lateral Walk is a lower body stepping exercise that targets your full body. Using dumbbells requires more stabilization than barbell variations. Leg training boosts metabolism and builds functional, real-world strength.', '74811201', '74811201-Dumbbell-Lateral-Walk-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.678791+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lateral Walk. 2. Set up in the starting position for Dumbbell Lateral Walk. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'walking', 'Lateral Walk', 'lat_pulldown, bent_over_row, pull_up', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('3fc55eb9-d094-402a-b044-8c27f2d64b32', 'Kneeling High Low Anti Rotation Ch (Resistance Band)', 'Core', 'Resistance Band, Anchor Point', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Resistance Band Kneeling High Low Anti Rotation Ch is a core rotation exercise that primarily targets your core. The obliques assist throughout the movement, making this a well-rounded exercise. The kneeling position adds a core stability challenge. The band creates increasing tension as it stretches, challenging the lockout. Building core stability helps with everything from heavy deadlifts to daily activities.', '65961201', '65961201-Resistance-Band-Kneeling-High-Low-Anti-Rotation-Ch.mp4', 'male', FALSE, '2025-12-03 23:26:21.995567+00', '1. Secure the resistance band appropriately for Resistance Band Kneeling High Low Anti Rotation Ch. 2. Kneel on the floor (use a pad for comfort if needed). 3. Rotate your torso through the movement pattern for Resistance Band Kneeling High Low Anti Rotation Ch. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'Kneeling High Low Anti Rotation Ch', 'woodchop, plank, dead_bug', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('3fda0560-464d-44e9-b722-bad16f729371', 'Twist Punch Shuffle', 'Full Body', 'Bodyweight', '{"Shoulders"}'::text[], '{"Biceps","Triceps","Core"}'::text[], 'Build power and athleticism with this high-intensity twisting exercise that challenges your entire body. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '71451201', '71451201-Twist-Punch-Shuffle-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Rotate your torso through the movement pattern for Twist Punch Shuffle. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'shuffle', 'Twist Punch Shuffle', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('3fdad9e7-c64c-474a-8ec8-ca4befdf0953', 'Safety Bar Good Morning', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'The Safety Bar Good Morning targets your hamstrings through a controlled movement motion. Secondary activation of your glutes, lower back provides additional muscle engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '59111201', '59111201-Safety-Bar-Good-Morning-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Set up in the starting position for Safety Bar Good Morning. 2. Execute the movement with proper form, focusing on your hamstrings. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_extension', 'Safety Bar Good Morning', 'romanian_deadlift, back_extension, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3fe11358-85b9-4189-b61c-3705a9521981', 'Crab Walk', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '58811201', '58811201-Crab-Walk-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Set up in the starting position for Crab Walk. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'walking', 'Crab Walk', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('3fe8d130-b5f9-4019-baa6-e8017cd6b6c5', 'Standing Side Stretch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this stretching movement that works your abs. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '21191201', '21191201-Standing-Side-Stretch_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Begin in a standing position with good posture. 2. Set up in the starting position for Standing Side Stretch. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'lat_stretch', 'Standing Side Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('3fea9eba-5830-4b67-bac3-cb86f951fba2', 'Squat And Hip Extension - Alternating', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '94551201', '94551201-Squat-and-Alternating-Hip-Extension-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:38.153182+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'glute_kickback', 'Squat And Hip Extension - Alternating', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('3fede116-5593-4e47-8f4a-cdd3de63dbc1', 'PVC Good Morning', 'Back', 'Bodyweight', '{"Lower Back"}'::text[], '{"Hamstrings","Glutes"}'::text[], 'The PVC Good Morning targets your hamstrings through a controlled movement motion. Your glutes, lower back work as secondary movers, adding to the training stimulus. Leg training boosts metabolism and builds functional, real-world strength.', '46041201', '46041201-PVC-Good-Morning_Hips.mp4', 'male', FALSE, '2025-12-03 23:26:22.247914+00', '1. Set up in the starting position for PVC Good Morning. 2. Execute the movement with proper form, focusing on your hamstrings. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_extension', 'PVC Good Morning', 'romanian_deadlift, back_extension, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('40090705-e11b-42f0-a457-a7294ce87147', 'Knee And Palm March', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Knee And Palm March is an explosive exercise that combines cardiovascular training with dynamic movement movements. You''ll also feel your hip flexors working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '57641201', '57641201-Knee-and-Palm-March-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Set up in the starting position for Knee And Palm March. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'marching', 'Knee And Palm March', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('401758ac-a29b-47e9-8f04-2f8ec4ca7866', 'Fly (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your front delts working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '3081201', '03081201-Dumbbell-Fly_Chest-FIX2_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'general_exercise', 'Fly', 'bench_press, incline_bench_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('40204c70-3420-4785-9175-afc2e49fbf08', 'Double Pulsing Squat Forward Backward', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength. Keep your core engaged throughout the exercise.', '96381201', '96381201-Double-Pulsing-Squat-Forward-Backward-(female)_Hip.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep. This variation specifically emphasizes the quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'pulse', 'Double Pulsing Squat Forward Backward', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('404542cc-6d14-4e5f-91be-b07bb86d5751', 'Cossack Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Cossack Squats is a squatting exercise that primarily loads your quadriceps. Secondary activation of your glutes, hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '25691201', '25691201-Cossack-Squats-(female)_Thighs.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Keep your core engaged for stability. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Cossack Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('404b3e25-56f2-4387-b2ea-2cf98488ace6', 'Seated Roll Leg (Stick)', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Stick Seated Roll Leg helps improve mobility and prevent stiffness. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '98231201', '98231201-Stick-Sitting-Roll-Leg-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Stick Seated Roll Leg. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Stick Seated Roll Leg', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('404ec862-2ab0-443f-811d-f5799920bf75', 'Behind The Head Ball Slam', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Behind The Head Ball Slam is an explosive exercise that combines cardiovascular training with dynamic movement movements. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '65301201', '65301201-Behind-the-Head-Ball-Slam-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.938497+00', '1. Set up in the starting position for Behind The Head Ball Slam. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Behind The Head Ball Slam', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('404f693a-18e8-4be6-8555-0f7ed2af2a8c', 'Twist March', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity twisting exercise that challenges your entire body. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning. Progress gradually by increasing resistance over time.', '53181201', '53181201-Twist-March-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Rotate your torso through the movement pattern for Twist March. 2. Control the rotation in both directions—avoid using momentum. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Twist March', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('40564ff8-3790-42f4-be96-a5e2a15ee893', 'Elevated Heel Goblet Squat (Dumbbell)', 'Legs', 'Dumbbells, Step Platform', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. The dumbbell variation provides freedom of movement and greater range of motion. Lower body strength improves everything from walking to heavy compound lifts. A staple exercise that belongs in most training programs.', '105741201', '105741201-Dumbbell-Elevated-Heel-Goblet-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Elevated Heel Goblet Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'goblet_squat', 'Elevated Heel Goblet Squat', 'squat, front_squat, lunge', TRUE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('4063c19a-2bb4-48ce-b89a-1f822fb35c5d', 'Tip Toe Knee Thrust', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This dynamic thrusting movement gets your heart rate up while developing explosive strength. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '84661201', '84661201-Tip-Toe-Knee-Thrust-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.623429+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set. This exercise is excellent for full body development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'knee_drive', 'Tip Toe Knee Thrust', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('406712e9-1b25-44aa-9f2a-a64c313789c9', 'Speed Step (Resistance Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{"Quads"}'::text[], 'The Resistance Band Speed Step is a lower body stepping exercise that targets your full body. You''ll also feel your quads working to support the movement. The band creates increasing tension as it stretches, challenging the lockout. Leg training boosts metabolism and builds functional, real-world strength.', '88741201', '88741201-Resistance-Band-Speed-Step-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.987963+00', '1. Secure the resistance band appropriately for Resistance Band Speed Step. 2. Set up a box or step platform at the appropriate height. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'general_exercise', 'Speed Step', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('4075e10a-63a2-4a17-adc1-b7fa2fa7a275', 'Single Straight Leg Glute Bridge Hold', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Develop your posterior chain with this bridging movement that emphasizes the glutes. Secondary activation of your hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '64941201', '64941201-Single-Straight-Leg-Glute-Bridge-Hold-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Hold the position for the prescribed time, maintaining tension. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Single Straight Leg Glute Bridge Hold', 'deadlift, leg_curl, hip_thrust', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('407a1905-6801-45ab-8574-7a65fad072d4', 'Hanging Leg Raise (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hamstrings"}'::text[], 'Build leg strength with this raising movement focusing on your abs. Your hip flexors work as secondary movers, adding to the training stimulus. The hanging position challenges your grip while targeting the primary muscles. This bodyweight exercise requires no equipment and can be done anywhere. Leg training boosts metabolism and builds functional, real-world strength.', '4721201', '04721201-Hanging-Leg-Raise_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Hanging Leg Raise', 'crunch, plank, v_up', FALSE, 'pull_up_bar', FALSE, 3, 60, 2, 70, 88, 95, 65),
('407c3d4a-5174-48e4-b8f6-45b44488c516', 'Kneeling Glute Kickback (Cable)', 'Legs', 'Cables', '{"Glutes","Hamstrings"}'::text[], '{"Rear Delts"}'::text[], 'Build stronger glutes with this kicking movement focused on hip extension. Secondary activation of your hamstrings provides additional muscle engagement. The kneeling position adds a core stability challenge. Cable resistance creates smooth, continuous muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '80881201', '80881201-Cable-Kneeling-Glute-Kickback-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:28.851102+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Glute Kickback. 2. Kneel on the floor (use a pad for comfort if needed). 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'glute_kickback', 'Kneeling Glute Kickback', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('40835b50-f6f3-431b-8f05-373227c2f6c2', 'Standing Upper And Lower Back Clap - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This full-body movement exercise challenges multiple muscle groups simultaneously. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Full body exercises are time-efficient and build functional, real-world strength.', '95381201', '95381201-Standing-Alternating-Upper-And-Lower-Back-Clap-(fe.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Begin in a standing position with good posture. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout. Perfect for targeting your full body.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'back_exercise', 'Standing Upper And Lower Back Clap - Alternating', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('4092f610-725b-44a2-87c5-05865dd77c32', 'Cross Standing Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This dynamic crunching movement gets your heart rate up while developing explosive strength. You''ll also feel your shoulders, core working to support the movement. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '58461201', '58461201-Cross-Standing-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Stand tall with your feet firmly planted. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'crunch', 'Cross Standing Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('40a24e1a-fccc-483f-9663-eeb8974d9c60', 'Standing Up Raise Side Twist', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Abs"}'::text[], 'The Standing Up Raise Side Twist is an explosive exercise that combines cardiovascular training with dynamic raising movements. The abs assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '84101201', '84101201-Standing-Up-Raise-Side-Twist-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Stand with feet about shoulder-width apart. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Up Raise Side Twist', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('40b62c25-c4fc-48f9-85fe-3265bcfbaf20', 'Seesaw Press (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Build stronger shoulders with this pressing movement focusing on your delts. The kettlebell grip position adds a unique training stimulus. Shoulder development enhances both performance and upper body aesthetics.', '72831201', '72831201-Kettlebell-Seesaw-Press-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Select an appropriately weighted kettlebell for Kettlebell Seesaw Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions. Exhale during the exertion phase of the movement. Ideal for delts strength and endurance.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'squeeze_press', 'Seesaw Press', 'squat, bench_press, deadlift', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('40be7b4b-fd75-42b9-b915-28724abe2219', 'Incline Curl II (Dumbbell)', 'Arms', 'Dumbbells, Incline Bench', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. Your forearms work as secondary movers, adding to the training stimulus. The incline angle shifts emphasis toward the upper portion of the target muscles. Using dumbbells requires more stabilization than barbell variations. Dedicated arm training builds both strength and muscular definition.', '3171201', '03171201-Dumbbell-Incline-Curl-II_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:26.808474+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Curl II. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 95, 5, 7, FALSE, TRUE, 'incline_curl', 'Incline Curl II', 'bicep_curl, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('40cc51e7-0bf4-4828-9ef3-c5a0125af666', 'Side Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Inner Thighs"}'::text[], 'Target the front of your thighs with this lunging exercise for quad development. You''ll also feel your glutes, hamstrings working to support the movement. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness. Control the negative portion for maximum muscle engagement.', '29731201', '29731201-Side-Lunge-(female)_Thighs-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Step to the side, bending that knee while keeping the other leg straight. 2. Push through your front/working leg to return to the starting position. 3. Continue for your target rep count, maintaining good form throughout. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'lunge', 'Side Lunge', 'split_squat, step_up, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('40cec5c0-e7c9-4843-b6d5-dfccf3329192', 'Lying Windshield Wiper', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Lying Windshield Wiper, focusing on your abs. The lying position provides back support and helps isolate the target muscles. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '71271201', '71271201-Lying-Windshield-Wiper-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Windshield Wiper. 2. Set up in the starting position for Lying Windshield Wiper. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Windshield Wiper', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('40d6704c-d332-42a1-940e-a49003cea912', 'Standing Forward Double Tap And Open', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Forward Double Tap And Open is a movement exercise that targets your chest muscles. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '95421201', '95421201-Standing-Forward-Double-Tap-And-Open-(female)_Ches.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Forward Double Tap And Open. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Forward Double Tap And Open', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('40ebedb3-5b7d-4dd0-b449-bd674bb7db83', 'Standing Chest Press (Resistance Band)', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your triceps, front delts working to support the movement. Performing this standing challenges your balance and core engagement. Bands are joint-friendly and portable, perfect for any training environment. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '91431201', '91431201-Resistance-Band-Standing-Chest-Press-(female)_Ches.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Standing Chest Press. 2. Stand tall with your feet firmly planted. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'bench_press', 'Standing Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('40f94447-cb51-4f95-b12d-1746efaaf226', 'Standing Side Leg Raise', 'Legs', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Standing Side Leg Raise is a lower body raising exercise that targets your hip abductors. Secondary activation of your glutes provides additional muscle engagement. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '46411201', '46411201-Standing-Side-Leg-Raise-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand with feet about shoulder-width apart. 2. Keeping legs mostly straight, raise them toward the ceiling. 3. Lower with control, stopping just before touching down. 4. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Standing Side Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('40fb7a92-d9d2-4822-8025-ce63e26f2c16', 'Seated Bicep Curl (Chair)', 'Arms', 'Chair', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'Build bigger biceps with this curling movement that targets the front of your arms. The forearms assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Arm strength supports grip, pulling, and pushing in compound movements.', '90881201', '90881201-Sitting-Biceps-Curl-on-a-Chair-(female)_Upper-Arms.mp4', 'female', FALSE, '2025-12-03 23:26:37.628647+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'bicep_curl', 'Seated Biceps Curl On A Chair', 'hammer_curl, preacher_curl, cable_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('410b213f-0f2e-4335-bb79-35555733ae07', 'Standing Single Delt Row (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. You''ll also feel your biceps, rear delts working to support the movement. The standing position engages your core for stability. Cable resistance creates smooth, continuous muscle engagement. A strong back improves posture, prevents injury, and balances pressing movements.', '79361201', '79361201-Cable-Standing-Single-Delt-Row-(VERSION-2)-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:20.847006+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Single Delt Row. 2. Begin in a standing position with good posture. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing Single Delt Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('410f0574-64db-4305-bba0-d740bcee6ec3', 'Reverse Fly (Machine)', 'Shoulders', 'Machine', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build stronger shoulders with this flying movement focusing on your rear delts. You''ll also feel your upper back working to support the movement. The seated position helps isolate the target muscles by removing momentum. The fixed path allows you to focus purely on muscular effort. Strong shoulders improve overhead strength and support nearly all upper body movements.', '6021201', '06021201-Lever-Seated-Reverse-Fly_Shoulders-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Reverse Fly. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'rear_delt', 'Lever Seated Reverse Fly', 'bench_press, incline_bench_press, push_up', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('413647ed-1774-4c3f-a372-ae978c572963', 'Standing Folded Arm Lift And Side Nudge', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build a stronger chest with this movement movement that develops pressing power. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '94831201', '94831201-Standing-Folded-Arm-Lift-And-Side-Nudge-(female)_C.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Folded Arm Lift And Side Nudge. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'arm_exercise', 'Standing Folded Arm Lift And Side Nudge', 'shoulder_press, lateral_raise, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('4137627a-e5cc-4936-b030-eecff499abb4', 'Seated Foot Extensors Stretch (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Seated Foot Extensors Stretch On A Chair helps improve mobility and prevent stiffness. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '92681201', '92681201-Sitting-Foot-Extensors-Stretch-on-a-Chair-(female).mp4', 'female', FALSE, '2025-12-03 23:26:37.756436+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Foot Extensors Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'stretch_general', 'Seated Foot Extensors Stretch On A Chair', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('413ca7b2-3a77-496a-8c17-f3d3f9848b13', 'Kneeling Single Arm Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Cable Kneeling Single Arm Fly is a flying exercise that targets your chest muscles. Secondary activation of your front delts provides additional muscle engagement. The kneeling position adds a core stability challenge. Cable resistance creates smooth, continuous muscle engagement. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '83161201', '83161201-Cable-Kneeling-Single-Arm-Fly-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Adjust the cable machine to the correct height and attachment for Cable Kneeling Single Arm Fly. 2. Kneel on the floor (use a pad for comfort if needed). 3. With a slight bend in your elbows, move the weight in a wide arc. 4. Squeeze your chest muscles at the center/top of the movement. 5. Return with control, feeling the stretch at the bottom. 6. Complete all reps on one side, then switch to the other side. 7. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'chest_fly', 'Kneeling Single Arm Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('41497b2b-0b85-4c1b-b3e8-a70707916695', 'Side Step Pick And Carry', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Step Pick And Carry is an explosive exercise that combines cardiovascular training with dynamic stepping movements. Secondary activation of your quads provides additional muscle engagement. Great for improving athletic performance, burning calories, and building conditioning.', '75721201', '75721201-Side-Step-Pick-and-Carry-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.422129+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Pick And Carry. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Side Step Pick And Carry', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('414caacf-2fa9-4811-adbf-6891bb07cd6c', 'Seated Switch Jump With Arms Lift (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'A challenging plyometric exercise, the Seated Switch Jump With Arms Lift On Chair builds reactive power and improves conditioning. Secondary activation of your quads, calves provides additional muscle engagement. The seated position helps isolate the target muscles by removing momentum. Great for improving athletic performance, burning calories, and building conditioning.', '104911201', '104911201-Seated-Switch-Jump-with-Arms-LIft-on-Chair-(male).mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 37, 9, 8, TRUE, TRUE, 'arm_exercise', 'Seated Switch Jump With Arms Lift On Chair', 'shoulder_press, lateral_raise, front_raise', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('4158eeb7-31a3-4452-a82f-e9b42223ae38', 'Triceps Extension In Cross Legged Positio (Dumbbell)', 'Arms', 'Dumbbells', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'The Dumbbell Triceps Extension In Cross Legged Positio targets your triceps through a extension motion. The dumbbell variation provides freedom of movement and greater range of motion. Dedicated arm training builds both strength and muscular definition.', '91991201', '91991201-Dumbbell-Triceps-Extension-in-Cross-Legged-Positio.mp4', 'female', FALSE, '2025-12-03 23:26:33.298565+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Triceps Extension In Cross Legged Positio. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'tricep_extension', 'Triceps Extension In Cross Legged Positio', 'tricep_pushdown, close_grip_bench', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('415eaba3-80b1-49c7-b174-11745b16d9ec', 'Side To Side Hop', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning. Control the negative portion for maximum muscle engagement.', '89161201', '89161201-Side-to-Side-Hop-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Set up in the starting position for Side To Side Hop. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'hop', 'Side To Side Hop', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('416290e0-d47e-4579-870d-f58a94a2732d', 'Puppy Pose', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Puppy Pose is a flexibility exercise that targets your shoulders, helping to release tension and improve range of motion. You''ll also feel your upper back, chest working to support the movement. Flexibility work like this enhances performance and prevents stiffness.', '67261201', '67261201-Puppy-Pose-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:29.483269+00', '1. Move into the stretch position for Puppy Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Don''t rush—quality over quantity.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'general_exercise', 'Puppy Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('416e50f3-7280-4072-99f6-d892577eaa56', 'Standing Assisted Abduction With Rope', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your hip abductors. You''ll also feel your glutes working to support the movement. Performing this standing challenges your balance and core engagement. Strong legs are the foundation for athletic performance and functional fitness.', '91861201', '91861201-Standing-Assisted-Abduction-with-Rope-(female)_Sho.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Assisted Abduction With Rope. 3. Execute the movement with proper form, focusing on your hip abductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'hip_abduction', 'Standing Assisted Abduction With Rope', 'plank, crunch, leg_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('416f6ffa-4448-45cd-9ddf-35391c4950da', 'Standing Hip Abduction (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'Build leg strength with this movement movement focusing on your hip abductors. Your glutes work as secondary movers, adding to the training stimulus. Performing this standing challenges your balance and core engagement. Resistance bands provide accommodating resistance that increases through the range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '80781201', '80781201-Resistance-Band-Standing-Hip-Abduction-(female)_Hi.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Standing Hip Abduction. 2. Stand tall with your feet firmly planted. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'hip_abduction', 'Standing Hip Abduction', 'hip_adduction, glute_bridge, clamshell', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('4174de38-0385-4d1c-b2a5-3b01b97a9e3e', 'Seated Sciatic Nerve Mobilization', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery. Start with lighter weight to master the movement pattern.', '99821201', '99821201-Sitting-Sciatic-Nerve-Mobilization-(female)_Stretc.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Sciatic Nerve Mobilization. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 38, 2, 6, FALSE, TRUE, 'mobility', 'Seated Sciatic Nerve Mobilization', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('41815f73-26de-4d98-93fc-26343d1c2d31', 'Seated Calf Raise (Dumbbell)', 'Legs', 'Dumbbells, Flat Bench', '{"Calves"}'::text[], '{}'::text[], 'The Dumbbell Seated Calf Raise isolates your calf muscles through a raising motion. Being seated provides stability, allowing you to focus on the working muscles. Using dumbbells requires more stabilization than barbell variations. Lower body strength improves everything from walking to heavy compound lifts.', '30821201', '30821201-Dumbbell-Seated-Calf-Raise-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Calf Raise. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'calf_raise', 'Seated Calf Raise', 'calf_raise, standing_calf_raise', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('41889a20-78b7-48fd-b992-6a1081cf2659', 'Side Step Sprinting Arms', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Side Step Sprinting Arms builds reactive power and improves conditioning. Great for improving athletic performance, burning calories, and building conditioning.', '81701201', '81701201-Side-Step-Sprinting-Arms-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:37.303932+00', '1. Set up a box or step platform at the appropriate height. 2. Set up in the starting position for Side Step Sprinting Arms. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'sprint', 'Side Step Sprinting Arms', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('418a792e-b633-4d35-9e4c-34eec3ff2b12', 'Incline Pullover (Dumbbell)', 'Chest', 'Dumbbells, Incline Bench', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger back with this pulling movement targeting your chest. The lats, triceps assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. The dumbbell variation provides freedom of movement and greater range of motion. Back development is crucial for pulling strength and overall upper body function.', '83331201', '83331201-Dumbbell-Incline-Pullover-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Incline Pullover. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'pullover', 'Incline Pullover', 'bicep_curl, face_pull, lat_pulldown', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('41957d06-f644-4cd8-945d-7d2cb31d8624', 'Single Leg Kas Glute Bridge', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. You''ll also feel your hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness.', '56711201', '56711201-Bodyweight-Single-Leg-Kas-Glute-Bridge_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps on one side, then switch to the other side. 5. Repeat for the prescribed number of repetitions. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 65, 7, 8, TRUE, TRUE, 'glute_bridge', 'Single Leg Kas Glute Bridge', 'hip_thrust, romanian_deadlift', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('4196487a-ccd0-4a85-8bc5-b62703a96f6b', 'Bent Over Row - Bench (Dumbbell)', 'Back', 'Dumbbells, Flat Bench', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, lats working to support the movement. Bending over allows gravity to provide resistance in a different plane. Using dumbbells requires more stabilization than barbell variations. A strong back improves posture, prevents injury, and balances pressing movements.', '2921201', '02921201-Dumbbell-Bent-over-Row_Back-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'bent_over_row', 'Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', FALSE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('419bbde3-8c99-4c1c-ba00-83cefe905004', 'Single Arm Punch And Side Knee Raise', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Single Arm Punch And Side Knee Raise is an explosive exercise that combines cardiovascular training with dynamic raising movements. The hip flexors assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '66651201', '66651201-Single-Arm-Punch-and-Side-Knee-Raise-(male)_Plyome.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Raise your arms out to the sides until parallel to the floor. 2. Lower with control, maintaining tension throughout. 3. Complete all reps on one side, then switch to the other side. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'leg_raise', 'Single Arm Punch And Side Knee Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('419fedac-5261-4d22-b42a-5e8d9b5e5935', 'Bent Knee Back To Side Kick', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build leg strength with this kicking movement focusing on your full body. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '46681201', '46681201-Bent-Knee-Back-to-Side-Kick-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:31.347577+00', '1. Set up in the starting position for Bent Knee Back To Side Kick. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'back_exercise', 'Bent Knee Back To Side Kick', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('41a5cc52-fb9e-46a4-b907-3558619017f2', 'Couch Stretch', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'This stretch specifically works on your full body, promoting flexibility and reducing muscle tightness. Include this in your routine for better mobility and reduced muscle tension. Control the negative portion for maximum muscle engagement.', '45571201', '45571201-Couch-Stretch_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Move into the stretch position for Couch Stretch. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 10, 2, 6, FALSE, TRUE, 'quad_stretch', 'Couch Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('41b03cae-6ba7-4943-a76b-7fe598723db2', 'Standing Torso Twist Arms Swing', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Secondary activation of your abs provides additional muscle engagement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '96531201', '96531201-Standing-Torso-Twist-Arms-Swing-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Begin in a standing position with good posture. 2. Rotate your torso through the movement pattern for Standing Torso Twist Arms Swing. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Standing Torso Twist Arms Swing', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('41b23391-c3dd-4340-a6dd-064d899bc22c', 'Lying Rear Delt Row (Kettlebell)', 'Shoulders', 'Kettlebell', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This rowing exercise strengthens the muscles between your shoulder blades. You''ll also feel your upper back working to support the movement. The lying position provides back support and helps isolate the target muscles. Kettlebells are excellent for building functional, real-world strength. Back development is crucial for pulling strength and overall upper body function.', '68351201', '68351201-Kettlebell-Lying-Rear-Delt-Row_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.288245+00', '1. Select an appropriately weighted kettlebell for Kettlebell Lying Rear Delt Row. 2. Lie down in the appropriate position for Kettlebell Lying Rear Delt Row. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'rear_delt', 'Lying Rear Delt Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'kettlebell', FALSE, 3, 90, 4, 75, 88, 88, 78),
('41b432bb-08d8-4352-9b61-05d0edc45048', 'Standing Rear Delt Row (Band)', 'Shoulders', 'Resistance Band, Anchor Point', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'This rowing exercise works your rear delts for improved shoulder strength and aesthetics. You''ll also feel your upper back working to support the movement. Performing this standing challenges your balance and core engagement. Resistance bands provide accommodating resistance that increases through the range of motion. Shoulder development enhances both performance and upper body aesthetics.', '10221201', '10221201-Band-standing-rear-delt-row_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Secure the resistance band appropriately for Band Standing Rear Delt Row. 2. Stand tall with your feet firmly planted. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'rear_delt', 'Standing Rear Delt Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('41bee327-fe3f-42a6-ae86-06173344957a', 'Seated W Pose (Chair)', 'Full Body', 'Chair', '{"Full Body"}'::text[], '{}'::text[], 'Designed to lengthen your full body, the Seated W Pose On A Chair helps improve mobility and prevent stiffness. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '91001201', '91001201-Sitting-W-Pose-on-a-Chair-(female)_Back_.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated W Pose On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 35, 2, 6, FALSE, TRUE, 'general_exercise', 'Seated W Pose On A Chair', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('41d51bd0-d3cc-4b06-98ee-15805acabd6d', 'Chest Press (Machine)', 'Chest', 'Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Lever Chest Press is a pressing exercise that targets your chest muscles. You''ll also feel your triceps, front delts working to support the movement. The fixed path allows you to focus purely on muscular effort. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '5771201', '05771201-Lever-Chest-Press_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps with control before resting. Maintain a neutral spine throughout. Include this in your chest training.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('41ee8ef4-f35b-49f0-8c37-f21c454bd225', 'Kneeling Reach And Thread', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Shoulders"}'::text[], 'The Kneeling Reach And Thread is a flexibility exercise that targets your upper back, helping to release tension and improve range of motion. You''ll also feel your shoulders working to support the movement. Kneeling helps eliminate lower body momentum from the movement. Include this in your routine for better mobility and reduced muscle tension.', '85481201', '85481201-Kneeling-Reach-and-Thread-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Move into the stretch position for Kneeling Reach And Thread. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Kneeling Reach And Thread', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('41ef31b9-b967-4de9-a3c2-50eddbbefc82', 'Standing Calf Raise (Barbell)', 'Legs', 'Barbell', '{"Calves"}'::text[], '{}'::text[], 'This raising movement focuses on your gastrocnemius and soleus. The standing position engages your core for stability. The barbell allows you to handle heavier loads for maximum strength gains. Leg training boosts metabolism and builds functional, real-world strength.', '26681201', '26681201-Barbell-Standing-Calf-Raise-(female)_Calves_.mp4', 'female', FALSE, '2025-12-03 23:26:31.133197+00', '1. Grip a barbell with hands at the appropriate width for Barbell Standing Calf Raise. 2. Begin in a standing position with good posture. 3. Lower your heels below the platform to get a full stretch. 4. Rise up onto your toes as high as possible, squeezing your calves. 5. Lower with control and repeat. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 94, 5, 7, FALSE, TRUE, 'calf_raise', 'Standing Calf Raise', 'calf_raise, seated_calf_raise', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('421e9c19-63e1-4f1e-b5f2-22025cb156d5', 'Jack Plank (Medicine Ball)', 'Core', 'Medicine Ball', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Jack Plank (medicine Ball) is a core stabilization exercise that primarily targets your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. Building core stability helps with everything from heavy deadlifts to daily activities.', '25641201', '25641201-Jack-Plank-on-Medicine-Ball-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.196858+00', '1. Hold a medicine ball at the appropriate position for Jack Plank. 2. Hold your body in a straight line from head to heels. 3. Don''t let your hips sag or pike up—engage your core and glutes. 4. Breathe steadily while maintaining the position. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'plank', 'Jack Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'medicine_ball', FALSE, 3, 60, 4, 70, 88, 95, 65),
('42244530-106a-473d-91d3-247c91d8a370', 'Lying Triceps Extension Skull Crusher (Barbell)', 'Arms', 'Barbell, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. The lying position provides back support and helps isolate the target muscles. Using a barbell provides stability for progressive overload. Arm strength supports grip, pulling, and pushing in compound movements.', '601201', '00601201-Barbell-Lying-Triceps-Extension-Skull-Crusher_Upper-Arms.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Grip a barbell with hands at the appropriate width for Barbell Lying Triceps Extension Skull Crusher. 2. Lie down in the appropriate position for Barbell Lying Triceps Extension Skull Crusher. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 92, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lying Triceps Extension Skull Crusher', 'tricep_pushdown, close_grip_bench', TRUE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('4239e435-61cd-4123-8887-8b2d8e3ac5c5', 'Bent Over Row - Chest Supported (Machine)', 'Back', 'Machine', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'The Lever Bent Over Row (with Chest Support) is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps, lats working to support the movement. The bent over position requires core engagement to maintain a neutral spine. The machine guides your movement path for safer, more controlled repetitions. Back development is crucial for pulling strength and overall upper body function.', '65131201', '65131201-Lever-Bent-Over-Row-(with-chest-support)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'bent_over_row', 'Lever Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('423bbecb-2dfc-49d3-bf58-8fc8f95950a7', 'Lateral Pulldown With Mag Grip (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. You''ll also feel your biceps, upper back working to support the movement. The cable setup allows you to adjust the angle of resistance. Back development is crucial for pulling strength and overall upper body function. This is a great exercise for all fitness levels with proper scaling.', '80901201', '80901201-Cable-Lateral-Pulldown-with-Mag-Grip-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lateral Pulldown With Mag Grip. 2. Pull the bar/handle down toward your upper chest. 3. Drive your elbows down and back, squeezing your lats. 4. Control the weight back up without letting it yank your arms. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Lateral Pulldown With Mag Grip', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('4252d32e-f40e-4a8b-976a-2db7cad5dedb', 'Assisted Side Lying Adductors Stretch', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'Build leg strength with this stretching movement focusing on your adductors. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '17121201', '17121201-Assisted-Side-Lying-Adductors-Stretch_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Assisted Side Lying Adductors Stretch. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Lying', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_adduction', 'Assisted Side Lying Adductors Stretch', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('427247eb-93f4-4496-aadb-dc65267299ec', 'Cat Stretch M', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Use this stretch to open up your full body area and enhance overall flexibility. Include this in your routine for better mobility and reduced muscle tension. Control the negative portion for maximum muscle engagement.', '10511201', '10511201-Cat-Stretch-m_Back.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Move into the stretch position for Cat Stretch M. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'stretch_general', 'Cat Stretch M', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('42794cfa-9c2e-41a7-b6b8-9bde039cebee', 'Incline Bench Press (Barbell)', 'Chest', 'Barbell, Incline Bench', '{"Chest"}'::text[], '{"Front Delts","Triceps"}'::text[], 'Target your chest with the Barbell Incline Bench Press, an effective pressing movement for upper body strength. The triceps, front delts assist throughout the movement, making this a well-rounded exercise. The incline angle shifts emphasis toward the upper portion of the target muscles. Using a barbell provides stability for progressive overload. A well-developed chest contributes to upper body strength and aesthetics.', '23881201', '23881201-Barbell-Incline-Bench-Press-(female)_Chest.mp4', 'female', FALSE, '2025-12-03 23:26:31.013316+00', '1. Load a barbell and set it on a bench rack at the appropriate height. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout. Keep your core engaged for stability.', 'Horizontal/Incline Press', 'Push', 'Compound', 'Bilateral', NULL, 3, NULL, 10, 10, NULL, 4, 'Lying', NULL, 'Overhand (Pronated)', 'Slightly wider than shoulder length', 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 100, 7, 9, TRUE, FALSE, 'incline_press', 'Incline Bench Press', 'bench_press, shoulder_press, chest_fly', TRUE, 'barbell', FALSE, 4, 120, 4, 95, 80, 65, 95),
('428b4d71-5c80-4885-bd9d-206ef0783c2f', 'Frogger', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Frogger, focusing on your abs. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '37031201', '37031201-Frogger_Waist-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:24.698781+00', '1. Set up in the starting position for Frogger. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Frogger', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('4298ab4d-040b-4cbf-a1ad-d93ea4928b87', 'Weighted Leg Extension Crunch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{}'::text[], 'The Weighted Leg Extension Crunch is a core extension exercise that primarily targets your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '8361201', '08361201-Weighted-Leg-Extension-Crunch_Waist-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:40.037451+00', '1. Extend your legs until straight, squeezing your quads at the top. 2. Lower with control back to the starting position. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'leg_extension', 'Weighted Leg Extension Crunch', 'squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('42ad399f-086c-4756-b171-a1ee01bdea35', 'Standing Leg Half Circle (Against Wall)', 'Shoulders', 'Wall', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Build leg strength with this movement movement focusing on your delts. Performing this standing challenges your balance and core engagement. Leg training boosts metabolism and builds functional, real-world strength.', '86591201', '86591201-Standing-Leg-Half-Circle-against-Wall-(female)_Hip.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Position yourself at the appropriate distance from a wall. 2. Stand tall with your feet firmly planted. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 44, 7, 8, TRUE, TRUE, 'leg_exercise', 'Standing Leg Half Circle Against Wall', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('42ade308-9970-4912-969a-7c8698d92797', 'Double Knee To Toe Touch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. Your hip flexors work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '52931201', '52931201-Double-Knee-To-Toe-Touch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. Set up in the starting position for Double Knee To Toe Touch. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'toe_touch', 'Double Knee To Toe Touch', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('42af6fa6-82a2-4619-a97b-4304989cd561', 'Lying Arm Crossover', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Shoulders","Core"}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. Secondary activation of your shoulders, core provides additional muscle engagement. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '82921201', '82921201-Lying-Arm-Crossover-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:24.941834+00', '1. Lie down in the appropriate position for Lying Arm Crossover. 2. Set up in the starting position for Lying Arm Crossover. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_fly', 'Lying Arm Crossover', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('42b02bf5-b99e-4511-81b5-ea4fe6ee3ee1', 'Seal To Puppy Pose', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Seal To Puppy Pose is a flexibility exercise that targets your shoulders, helping to release tension and improve range of motion. Secondary activation of your upper back, chest provides additional muscle engagement. Include this in your routine for better mobility and reduced muscle tension.', '79041201', '79041201-Seal-to-Puppy-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Move into the stretch position for Seal To Puppy Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'general_exercise', 'Seal To Puppy Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('42b524aa-428a-4ea6-a8c6-f28c15bfead5', 'Lizard Pose', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Flexibility work like this enhances performance and prevents stiffness. Aim for full range of motion on every rep.', '58921201', '58921201-Lizard-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Move into the stretch position for Lizard Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 50, 2, 6, FALSE, TRUE, 'hip_stretch', 'Lizard Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('42c34fae-c568-449c-b967-cbf2f39fe192', 'Squat (Plate Loaded Machine)', 'Legs', 'Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Machine exercises are great for isolating muscles and training to failure safely. Leg training boosts metabolism and builds functional, real-world strength.', '57881201', '57881201-Lever-Squat-(plate-loaded)-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'squat', 'Lever Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
